#!/usr/bin/env python3

roman_values = {
    'I': 1,
    'V': 5,
    'X': 10,
    'L': 50,
    'C': 100,
    'D': 500,
    'M': 1000
}

def roman_to_int(s: str) -> int:
    """Convert Roman numeral to integer."""
    total = 0
    prev_value = 0

    for char in reversed(s):
        value = roman_values[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    return total

def is_valid_roman(s: str) -> bool:
    """Check if string is a valid Roman numeral according to standard rules."""
    # Basic validation: check characters are valid Roman numerals
    for char in s:
        if char not in roman_values:
            return False

    # Check for invalid repetitions
    # I, X, C, M can repeat up to 3 times
    # V, L, D cannot repeat
    for i in range(len(s) - 3):
        if s[i] == s[i+1] == s[i+2] == s[i+3]:
            return False

    # Check for valid subtractive combinations
    # Only these subtractive pairs are valid: IV, IX, XL, XC, CD, CM
    valid_subtractive_pairs = {'IV', 'IX', 'XL', 'XC', 'CD', 'CM'}

    for i in range(len(s) - 1):
        pair = s[i:i+2]
        if roman_values[s[i]] < roman_values[s[i+1]]:
            if pair not in valid_subtractive_pairs:
                return False

    # Check ordering: values should generally decrease from left to right
    # except for valid subtractive combinations
    for i in range(len(s) - 1):
        current = roman_values[s[i]]
        next_val = roman_values[s[i+1]]

        # If current is less than next, it must be a valid subtractive pair
        if current < next_val:
            pair = s[i:i+2]
            if pair not in valid_subtractive_pairs:
                return False
        # If current is much larger than next (except for repeats), could be invalid
        # but we'll let the standard conversion handle it

    return True

# Generate all three-letter palindromic Roman numerals
letters = list(roman_values.keys())
palindromic_numerals = []

for first in letters:
    for middle in letters:
        numeral = first + middle + first
        if is_valid_roman(numeral):
            value = roman_to_int(numeral)
            palindromic_numerals.append((numeral, value))
            print(f"{numeral}: {value}")

print(f"\nTotal valid palindromic three-letter Roman numerals: {len(palindromic_numerals)}")
print(f"Sum of their values: {sum(v for _, v in palindromic_numerals)}")

# Also print the list sorted by value
print("\nSorted by value:")
for numeral, value in sorted(palindromic_numerals, key=lambda x: x[1]):
    print(f"{numeral}: {value}")

